memberdef.initializer:
template <> inline type *Tensor::data<type>() {                                                  \
  if (is_raw_data_) {                                                                            \
    return reinterpret_cast<type *>(raw_data_.data());                                           \
  }                                                                                              \
  return field.data();                                                                           \
}                                                                                                \
                                                                                                 \
template <> inline const type *Tensor::data<type>() const {                                      \
  if (is_raw_data_) {                                                                            \
    return reinterpret_cast<const type *>(raw_data_.data());                                     \
  }                                                                                              \
  return field.data();                                                                           \
}
